package dev.qiandeng.maw;

import com.google.gson.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.nbt.TagParser;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.SimpleContainer;
import net.minecraft.world.SimpleMenuProvider;
import net.minecraft.world.inventory.ChestMenu;
import net.minecraft.world.item.*;
import net.minecraft.world.item.component.CustomData;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.resources.ResourceLocation;
import java.util.*;

/** Ten real 54-slot pages, no decorative loot icons; vanilla container semantics. */
final class RpgStorage {
    private static final Map<UUID,Page> OPEN=new HashMap<>();
    private record Quote(UUID player,String source,int slot,int count,String snbt,long price,long expires){}
    private static final Map<String,Quote> QUOTES=new HashMap<>();
    private static final Map<String,Offer> SHOP=Map.of("bread",new Offer("minecraft:bread",8,3),"arrows",new Offer("minecraft:arrow",16,4),"torches",new Offer("minecraft:torch",16,3),"iron_sword",new Offer("minecraft:iron_sword",1,12),"iron_chest",new Offer("minecraft:iron_chestplate",1,18),"shield",new Offer("minecraft:shield",1,10));
    private record Offer(String item,int count,long price){}
    private static final class Page extends SimpleContainer {
        final ServerPlayer owner;final int page;boolean loading=true;
        Page(ServerPlayer p,int page){super(54);owner=p;this.page=page;JsonObject saved=RpgStore.player(p).getAsJsonObject("stash");for(int n=0;n<54;n++){String slot=""+(page*54+n);if(saved.has(slot))setItem(n,decode(p,saved.get(slot).getAsString()));}loading=false;}
        @Override public void setChanged(){super.setChanged();if(!loading)save();}
        void save(){JsonObject saved=RpgStore.player(owner).getAsJsonObject("stash");for(int n=0;n<54;n++){String slot=""+(page*54+n);ItemStack stack=getItem(n);if(stack.isEmpty())saved.remove(slot);else saved.addProperty(slot,ModRequest.snbt(owner,stack));}RpgStore.dirty(owner);}
    }
    static ItemStack decode(ServerPlayer p,String snbt){try{return snbt.isEmpty()?ItemStack.EMPTY:ItemStack.parse(p.registryAccess(),TagParser.parseTag(snbt)).orElseThrow(()->new IllegalStateException("saved_item_not_decodable"));}catch(com.mojang.brigadier.exceptions.CommandSyntaxException failure){throw new IllegalStateException("saved_item_not_decodable",failure);}}
    static void open(ServerPlayer p,int page){if(page<0||page>=10)throw new IllegalArgumentException("stash_page_out_of_range");if(!p.containerMenu.getCarried().isEmpty())throw new IllegalArgumentException("clear_cursor_before_stash");drain(p);Page container=new Page(p,page);OPEN.put(p.getUUID(),container);
        p.openMenu(new SimpleMenuProvider((id,inventory,who)->new ChestMenu(net.minecraft.world.inventory.MenuType.GENERIC_9x6,id,inventory,container,6){@Override public boolean stillValid(net.minecraft.world.entity.player.Player who){return who==p&&p.isAlive()&&PlayerAuthBridge.authenticated(p);}@Override public void removed(net.minecraft.world.entity.player.Player who){super.removed(who);container.save();OPEN.remove(p.getUUID(),container);drain(p);}},Component.literal("个人试炼箱 · "+(page+1)+"/10")));
    }
    static ItemStack item(ServerPlayer p,int slot){Page page=OPEN.get(p.getUUID());if(page!=null&&slot/54==page.page)return page.getItem(slot%54).copy();JsonObject saved=RpgStore.player(p).getAsJsonObject("stash");return saved.has(""+slot)?decode(p,saved.get(""+slot).getAsString()):ItemStack.EMPTY;}
    private static void set(ServerPlayer p,int slot,ItemStack stack){Page page=OPEN.get(p.getUUID());if(page!=null&&slot/54==page.page){page.setItem(slot%54,stack);page.setChanged();}else{JsonObject saved=RpgStore.player(p).getAsJsonObject("stash");if(stack.isEmpty())saved.remove(""+slot);else saved.addProperty(""+slot,ModRequest.snbt(p,stack));RpgStore.dirty(p);}}
    static boolean hasRewardCapacity(ServerPlayer p,int stacks){drain(p);return stacks>=0&&RpgStore.player(p).getAsJsonArray("pending").size()<=2048-stacks;}
    static void enqueue(ServerPlayer p,List<ItemStack> rewards){if(!hasRewardCapacity(p,rewards.size()))throw new IllegalArgumentException("reward_queue_full_contact_operator");JsonArray pending=RpgStore.player(p).getAsJsonArray("pending");for(ItemStack item:rewards)if(!item.isEmpty())pending.add(ModRequest.snbt(p,item));RpgStore.dirty(p);drain(p);}
    static void drain(ServerPlayer p){JsonArray pending=RpgStore.player(p).getAsJsonArray("pending");if(pending.isEmpty())return;for(int n=0;n<pending.size();){ItemStack stack=decode(p,pending.get(n).getAsString());for(int i=0;i<540&&!stack.isEmpty();i++){ItemStack at=item(p,i);if(at.isEmpty()){set(p,i,stack.copy());stack.setCount(0);}else if(ItemStack.isSameItemSameComponents(stack,at)){int count=Math.min(stack.getCount(),at.getMaxStackSize()-at.getCount());if(count>0){at.grow(count);stack.shrink(count);set(p,i,at);}}}if(stack.isEmpty())pending.remove(n);else{pending.set(n,new JsonPrimitive(ModRequest.snbt(p,stack)));n++;break;}}RpgStore.dirty(p);}
    static JsonObject state(ServerPlayer p,int page){if(page<0||page>=10)throw new IllegalArgumentException("stash_page_out_of_range");JsonObject r=new JsonObject();JsonArray rows=new JsonArray();for(int n=page*54;n<(page+1)*54;n++){ItemStack stack=item(p,n);if(stack.isEmpty())continue;JsonObject row=info(p,stack);row.addProperty("slot",n);rows.add(row);}r.add("items",rows);r.addProperty("page",page+1);r.addProperty("pages",10);r.addProperty("capacity",540);r.addProperty("pendingStacks",RpgStore.player(p).getAsJsonArray("pending").size());return r;}
    static JsonObject info(ServerPlayer p,ItemStack s){JsonObject r=new JsonObject();r.addProperty("itemId",BuiltInRegistries.ITEM.getKey(s.getItem()).toString());r.addProperty("name",s.getHoverName().getString());r.addProperty("count",s.getCount());r.addProperty("damage",s.getDamageValue());r.addProperty("maxDamage",s.getMaxDamage());JsonArray enchants=new JsonArray();s.getEnchantments().entrySet().forEach(e->{JsonObject row=new JsonObject();row.addProperty("id",e.getKey().getRegisteredName());row.addProperty("level",e.getIntValue());enchants.add(row);});r.add("enchantments",enchants);r.addProperty("snbt",ModRequest.snbt(p,s));return r;}
    static boolean bound(ItemStack s){CustomData c=s.get(DataComponents.CUSTOM_DATA);if(c==null)return false;var tag=c.copyTag();return tag.getBoolean("maw_bound")||tag.getBoolean("maw_guide");}
    private static long value(ItemStack stack){if(stack.isEmpty()||bound(stack)||!stack.isDamageableItem()||stack.has(DataComponents.CONTAINER))return 0;var id=BuiltInRegistries.ITEM.getKey(stack.getItem());if(!id.getNamespace().equals("minecraft"))return 0;var custom=stack.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag();boolean reward=custom.getBoolean("maw_trial_reward");if(!reward&&(stack.has(DataComponents.CUSTOM_NAME)||!custom.isEmpty()))return 0;String path=id.getPath();if(!(path.startsWith("iron_")||path.startsWith("chainmail_")||path.startsWith("leather_")||path.equals("bow")||path.equals("crossbow")||path.equals("shield")))return 0;return Math.max(1,(long)((path.startsWith("iron_")?4:2)*(1-(double)stack.getDamageValue()/Math.max(1,stack.getMaxDamage()))));}
    private static Object economy(ServerPlayer p){try{return Class.forName("com.reazip.economycraft.EconomyCraft").getMethod("getManager",net.minecraft.server.MinecraftServer.class).invoke(null,p.getServer());}catch(ReflectiveOperationException e){throw new IllegalStateException("economy_unavailable",e);}}
    static long wallet(ServerPlayer p){try{Object result=economy(p).getClass().getMethod("getBalance",UUID.class,boolean.class).invoke(economy(p),p.getUUID(),false);return result==null?0:((Number)result).longValue();}catch(ReflectiveOperationException e){throw new IllegalStateException("economy_unavailable",e);}}
    private static void credit(ServerPlayer p,long price){try{economy(p).getClass().getMethod("addMoney",UUID.class,long.class).invoke(economy(p),p.getUUID(),price);}catch(ReflectiveOperationException e){throw new IllegalStateException("economy_unavailable",e);}}
    static JsonObject shop(ServerPlayer p){JsonObject r=new JsonObject();JsonArray rows=new JsonArray();SHOP.entrySet().stream().sorted(Map.Entry.comparingByKey()).forEach(e->{JsonObject row=new JsonObject();row.addProperty("id",e.getKey());row.addProperty("item",e.getValue().item);row.addProperty("count",e.getValue().count);row.addProperty("price",e.getValue().price);rows.add(row);});r.add("offers",rows);r.addProperty("balance",wallet(p));r.addProperty("currency","灯币");return r;}
    static JsonObject recyclable(ServerPlayer p){JsonArray rows=new JsonArray();for(String source:List.of("bag","chest")){int count=source.equals("bag")?36:540;for(int n=0;n<count;n++){ItemStack stack=source.equals("bag")?p.getInventory().getItem(n):item(p,n);long value=value(stack);if(value==0||source.equals("bag")&&n==p.getInventory().selected)continue;JsonObject row=info(p,stack);row.addProperty("source",source);row.addProperty("slot",n);row.addProperty("unitPrice",value);rows.add(row);if(rows.size()==48)break;}if(rows.size()==48)break;}JsonObject r=new JsonObject();r.add("items",rows);r.addProperty("limit",48);r.addProperty("balance",wallet(p));return r;}
    static JsonObject quote(ServerPlayer p,JsonObject input){String source=input.get("source").getAsString();int slot=input.get("slot").getAsInt(),count=input.get("count").getAsInt();if(!Set.of("bag","chest").contains(source)||slot<0||slot>=(source.equals("bag")?36:540))throw new IllegalArgumentException("invalid_storage_source_or_slot");ItemStack stack=source.equals("bag")?p.getInventory().getItem(slot):item(p,slot);if(count<1||count>stack.getCount()||value(stack)==0||source.equals("bag")&&slot==p.getInventory().selected)throw new IllegalArgumentException("item_not_recyclable");QUOTES.entrySet().removeIf(e->e.getValue().expires<System.currentTimeMillis());if(QUOTES.size()>=512)throw new IllegalArgumentException("quote_capacity_wait");String id=UUID.randomUUID().toString();Quote quote=new Quote(p.getUUID(),source,slot,count,ModRequest.snbt(p,stack),value(stack)*count,System.currentTimeMillis()+30000);QUOTES.put(id,quote);JsonObject r=info(p,stack);r.addProperty("quoteId",id);r.addProperty("quantity",count);r.addProperty("price",quote.price);r.addProperty("expiresAtEpochMs",quote.expires);return r;}
    static JsonObject sell(ServerPlayer p,String quoteId){Quote q=QUOTES.get(quoteId);if(q==null||!q.player.equals(p.getUUID())||q.expires<System.currentTimeMillis())throw new IllegalArgumentException("quote_invalid_or_expired");ItemStack stack=q.source.equals("bag")?p.getInventory().getItem(q.slot):item(p,q.slot);if(!ModRequest.snbt(p,stack).equals(q.snbt)||value(stack)==0||q.source.equals("bag")&&q.slot==p.getInventory().selected)throw new IllegalArgumentException("quoted_item_components_changed");QUOTES.remove(quoteId);JsonObject r=info(p,stack);stack=stack.copy();stack.shrink(q.count);if(q.source.equals("bag")){p.getInventory().setItem(q.slot,stack);p.inventoryMenu.broadcastChanges();}else set(p,q.slot,stack);credit(p,q.price);r.addProperty("quantity",q.count);r.addProperty("price",q.price);r.addProperty("balance",wallet(p));r.addProperty("ok",true);drain(p);return r;}
    static JsonObject buy(ServerPlayer p,String id){Offer offer=SHOP.get(id);if(offer==null)throw new IllegalArgumentException("shop_offer_not_found");if(RpgStore.player(p).getAsJsonArray("pending").size()>=2048)throw new IllegalArgumentException("reward_queue_full");try{boolean paid=(Boolean)economy(p).getClass().getMethod("removeMoney",UUID.class,long.class).invoke(economy(p),p.getUUID(),offer.price);if(!paid)throw new IllegalArgumentException("not_enough_balance");}catch(ReflectiveOperationException e){throw new IllegalStateException("economy_unavailable",e);}ItemStack item=new ItemStack(BuiltInRegistries.ITEM.get(ResourceLocation.parse(offer.item)),offer.count);ItemStack remaining=item.copy();p.getInventory().add(remaining);if(!remaining.isEmpty())enqueue(p,List.of(remaining));JsonObject r=info(p,item);r.addProperty("price",offer.price);r.addProperty("balance",wallet(p));r.addProperty("pendingStacks",RpgStore.player(p).getAsJsonArray("pending").size());r.addProperty("ok",true);return r;}
}
